/** Presets shown in Label Size dropdown — keep in sync with ajax/save-barcode-settings.php $valid_presets */
$bs_label_preset_ui = ['100x18', '100x25', '100x48', '100x80', '64x25', '81x12', '120x50', '250x120', 'custom'];
$bs_label_preset_saved = trim((string)($bs['label_size_preset'] ?? '100x18'));
if ($bs_label_preset_saved === '') {
    $bs_label_preset_saved = '100x18';
}
$bs_label_preset_for_select = in_array($bs_label_preset_saved, $bs_label_preset_ui, true)
    ? $bs_label_preset_saved
    : 'custom';
/* Map custom + mm dimensions back to a standard preset when they match (e.g. 100×18 saved as custom). */
if ($bs_label_preset_for_select === 'custom') {
    $bs_dim_preset = (int) round((float) ($bs['label_width_mm'] ?? 100)) . 'x' . (int) round((float) ($bs['label_height_mm'] ?? 18));
    if (in_array($bs_dim_preset, $bs_label_preset_ui, true)) {
        $bs_label_preset_for_select = $bs_dim_preset;
    }
}
